<script setup>defineProps({title:String,open:Boolean,closeable:{type:Boolean,default:true},size:{type:String,default:'normal'}});defineEmits(['close'])</script>
<template><Teleport to="body"><div v-if="open" class="modal-layer" @mousedown.self="closeable&&$emit('close')"><section class="modal" :class="{'modal-large':size==='large'}" role="dialog" aria-modal="true" :aria-label="title"><header><h2>{{title}}</h2><button v-if="closeable" class="icon-button" @click="$emit('close')" aria-label="Tancar">×</button></header><div class="modal-body"><slot/></div><footer><slot name="actions"/></footer></section></div></Teleport></template>
